def main():
    tg = json.load(open(os.path.join(HERE, "data", "rr_targets.json")))
    out = []
    for t in tg:
        r = t["sheet_row"]
        w, p1, p2, em, src, notes = S[r]
        out.append({"sheet_row": r, "company": t["company"], "website": w,
                    "main_phone": ph(*p1) if p1 else "", "phone_2": ph(*p2) if p2 else "",
                    "company_email": em, "source": src, "notes": notes})
    json.dump(out, open(OUT, "w"), indent=1, ensure_ascii=False)
    print(len(out), "records;", sum(bool(o["website"]) for o in out), "websites;",
          sum(bool(o["main_phone"]) for o in out), "main_phone;", sum(bool(o["phone_2"]) for o in out), "phone_2;",
          sum(bool(o["company_email"]) for o in out), "company_email")


if __name__ == "__main__":
    main()
